import { useEffect, useState } from "react";
//#region src/lib/media.ts
var DB_NAME = "northline-media";
var STORE = "files";
function openDb() {
	return new Promise((resolve, reject) => {
		const req = indexedDB.open(DB_NAME, 1);
		req.onupgradeneeded = () => {
			req.result.createObjectStore(STORE);
		};
		req.onsuccess = () => resolve(req.result);
		req.onerror = () => reject(req.error);
	});
}
function isRemoteSrc(src) {
	return src.startsWith("/") || src.startsWith("http://") || src.startsWith("https://") || src.startsWith("data:") || src.startsWith("blob:");
}
async function saveMediaBlob(blob) {
	const id = `media-${crypto.randomUUID()}`;
	const db = await openDb();
	await new Promise((resolve, reject) => {
		const tx = db.transaction(STORE, "readwrite");
		tx.objectStore(STORE).put(blob, id);
		tx.oncomplete = () => resolve();
		tx.onerror = () => reject(tx.error);
	});
	db.close();
	return id;
}
async function deleteMedia(id) {
	if (isRemoteSrc(id)) return;
	const db = await openDb();
	await new Promise((resolve, reject) => {
		const tx = db.transaction(STORE, "readwrite");
		tx.objectStore(STORE).delete(id);
		tx.oncomplete = () => resolve();
		tx.onerror = () => reject(tx.error);
	});
	db.close();
}
async function readMediaUrl(id) {
	if (!id) return null;
	if (isRemoteSrc(id)) return id;
	const db = await openDb();
	const blob = await new Promise((resolve, reject) => {
		const req = db.transaction(STORE, "readonly").objectStore(STORE).get(id);
		req.onsuccess = () => resolve(req.result);
		req.onerror = () => reject(req.error);
	});
	db.close();
	if (!blob) return null;
	return URL.createObjectURL(blob);
}
function useMediaUrl(src) {
	const [url, setUrl] = useState(() => src && isRemoteSrc(src) ? src : "");
	useEffect(() => {
		if (!src) {
			setUrl("");
			return;
		}
		if (isRemoteSrc(src)) {
			setUrl(src);
			return;
		}
		let live = true;
		let objectUrl = null;
		readMediaUrl(src).then((next) => {
			if (!live) return;
			if (next?.startsWith("blob:")) objectUrl = next;
			setUrl(next ?? "");
		});
		return () => {
			live = false;
			if (objectUrl) URL.revokeObjectURL(objectUrl);
		};
	}, [src]);
	return url;
}
//#endregion
export { saveMediaBlob as n, useMediaUrl as r, deleteMedia as t };
